import assert from "node:assert";
function main(): void {
  try { assert.deepStrictEqual(new Map([[1, 2]]), new Map([[1, 3]])); } catch (e: any) { console.log(e.message); }
  try { assert.deepStrictEqual(new Set([1]), new Set([2])); } catch (e: any) { console.log(e.message); }
  try { assert.deepStrictEqual(new Date(0), new Date(1)); } catch (e: any) { console.log(e.message); }
}
